@layer nz.tokens, nz.themes, nz.reset, nz.base, nz.components, nz.patterns, nz.utilities;

/* @nizivo/react/css/icon-button.css (ARCHITECTURE.md §10.2; figma/12 §4.9, set 7275:11357). Button's
   approach: variants, sizes and the toggle state set ONLY --_nz-* privates; public --nz-icon-button-*
   hooks are read once, at the property, and never assigned here. */
@layer nz.components {
  .nz-icon-button {
    /* defaults = Figma Secondary, 40 × 40, radius/md, 20 px glyph */
    --_nz-icon-button-bg: var(--nz-bg-surface);
    --_nz-icon-button-bg-hover: var(--nz-bg-hover);
    --_nz-icon-button-bg-pressed: var(--nz-bg-pressed);
    --_nz-icon-button-fg: var(--nz-text-primary);
    --_nz-icon-button-border: var(--nz-border-default);
    --_nz-icon-button-border-hover: var(--nz-border-strong);
    --_nz-icon-button-size: var(--nz-size-control-md);
    --_nz-icon-button-radius: var(--nz-radius-md);
    --_nz-icon-button-icon-size: var(--nz-size-icon-md);

    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    inline-size: var(--nz-icon-button-size, var(--_nz-icon-button-size));
    block-size: var(--nz-icon-button-size, var(--_nz-icon-button-size));
    padding: 0;
    border: var(--nz-border-width-default) solid
      var(--nz-icon-button-border, var(--_nz-icon-button-border));
    border-radius: var(--nz-icon-button-radius, var(--_nz-icon-button-radius));
    background: var(--nz-icon-button-bg, var(--_nz-icon-button-bg));
    color: var(--nz-icon-button-fg, var(--_nz-icon-button-fg));
    cursor: pointer;
    transition:
      background-color var(--nz-duration-fast) var(--nz-easing-standard),
      border-color var(--nz-duration-fast) var(--nz-easing-standard),
      color var(--nz-duration-fast) var(--nz-easing-standard),
      scale var(--nz-duration-instant) var(--nz-easing-standard);

    @media (hover: hover) {
      &:hover:not(:disabled, [data-disabled], [aria-disabled='true']) {
        background: var(--nz-icon-button-bg-hover, var(--_nz-icon-button-bg-hover));
        border-color: var(--nz-icon-button-border-hover, var(--_nz-icon-button-border-hover));
      }
    }

    &:active:not(:disabled, [data-disabled], [aria-disabled='true']) {
      background: var(--nz-icon-button-bg-pressed, var(--_nz-icon-button-bg-pressed));
      border-color: var(--nz-icon-button-border-hover, var(--_nz-icon-button-border-hover));
      scale: var(--nz-scale-press);
    }

    /* the 2 px outline lives in nz.base; this adds only the decorative halo */
    &:focus-visible {
      box-shadow: 0 0 0 calc(var(--nz-border-width-focus) + 4px) var(--nz-focus-halo);
    }

    &:is(:disabled, [data-disabled]) {
      background: var(--nz-icon-button-bg-disabled, var(--nz-bg-disabled));
      color: var(--nz-icon-button-fg-disabled, var(--nz-text-disabled));
      border-color: var(--nz-border-subtle);
      cursor: not-allowed;
    }

    &[data-pending] {
      cursor: progress;
    }
  }

  /* Figma Primary draws no highlight or shadow, unlike Primary Button (a Deviations entry) */
  .nz-icon-button[data-variant='primary'] {
    --_nz-icon-button-bg: var(--nz-bg-brand);
    --_nz-icon-button-bg-hover: var(--nz-bg-brand-hover);
    --_nz-icon-button-bg-pressed: var(--nz-bg-brand-pressed);
    --_nz-icon-button-fg: var(--nz-text-on-brand);
    --_nz-icon-button-border: transparent;
    --_nz-icon-button-border-hover: transparent;
  }

  .nz-icon-button[data-variant='tertiary'] {
    --_nz-icon-button-bg: transparent;
    --_nz-icon-button-border: transparent;
    --_nz-icon-button-border-hover: transparent;
  }

  /* not drawn in Figma: Button's Critical (§15.3) */
  .nz-icon-button[data-variant='critical'] {
    --_nz-icon-button-bg: var(--nz-bg-critical);
    --_nz-icon-button-bg-hover: var(--nz-bg-critical-hover);
    --_nz-icon-button-bg-pressed: var(--nz-bg-critical-hover);
    --_nz-icon-button-fg: var(--nz-text-on-critical);
    --_nz-icon-button-border: transparent;
    --_nz-icon-button-border-hover: transparent;
  }

  /* "reserved for AI features": docs guidance, not enforced */
  .nz-icon-button[data-variant='accent'] {
    --_nz-icon-button-bg: var(--nz-bg-accent);
    --_nz-icon-button-bg-hover: var(--nz-bg-accent-hover);
    --_nz-icon-button-bg-pressed: var(--nz-bg-accent-hover);
    --_nz-icon-button-fg: var(--nz-text-on-accent);
    --_nz-icon-button-border: transparent;
    --_nz-icon-button-border-hover: transparent;
  }

  /* A pressed toggle (not drawn; Tagged Product's Added state swaps the glyph and fill instead). The
     brand border is the 3:1 cue against the page; the tint and the brand glyph support it. Filled
     variants keep their fill and show it pressed. */
  .nz-icon-button:is([data-variant='secondary'], [data-variant='tertiary'])[aria-pressed='true'] {
    --_nz-icon-button-bg: var(--nz-bg-brand-subtle);
    --_nz-icon-button-bg-hover: var(--nz-bg-brand-subtle);
    --_nz-icon-button-fg: var(--nz-text-brand);
    --_nz-icon-button-border: var(--nz-border-brand);
    --_nz-icon-button-border-hover: var(--nz-border-brand);
  }

  .nz-icon-button:is(
      [data-variant='primary'],
      [data-variant='critical'],
      [data-variant='accent']
    )[aria-pressed='true'] {
    --_nz-icon-button-bg: var(--_nz-icon-button-bg-pressed);
    --_nz-icon-button-bg-hover: var(--_nz-icon-button-bg-pressed);
  }

  .nz-icon-button[data-size='sm'] {
    --_nz-icon-button-size: var(--nz-size-control-sm);
    --_nz-icon-button-radius: var(--nz-radius-sm);
    --_nz-icon-button-icon-size: var(--nz-size-icon-sm);
  }

  .nz-icon-button[data-size='lg'] {
    --_nz-icon-button-size: var(--nz-size-control-lg);
    --_nz-icon-button-icon-size: var(--nz-size-icon-lg);
  }

  .nz-icon-button-icon {
    display: inline-flex;
    inline-size: var(--_nz-icon-button-icon-size);
    block-size: var(--_nz-icon-button-icon-size);
    /* internal glyphs are 1em: size them to the slot */
    font-size: var(--_nz-icon-button-icon-size);

    & > svg {
      inline-size: 100%;
      block-size: 100%;
    }
  }

  /* One turn per --nz-duration-spin (Figma duration/spin). Reduced motion sets it to 0 ms, so the
     loop never runs and the glyph rests upright (§13.2). An icon-only button has no room for the
     "Loading…" text Button shows then: the static glyph and aria-disabled are its whole cue. */
  .nz-icon-button[data-pending] .nz-glyph-spinner {
    animation: nz-icon-button-spin var(--nz-duration-spin) linear infinite;
  }

  @keyframes nz-icon-button-spin {
    to {
      rotate: 1turn;
    }
  }

  @media (forced-colors: active) {
    .nz-icon-button {
      border-color: ButtonText;
    }

    /* repeated from the generated stateIndicator rule, which this file's background would beat (§8.5) */
    .nz-icon-button[aria-pressed='true'] {
      border-color: Highlight;
      background: Highlight;
      color: HighlightText;
      forced-color-adjust: none;
    }
  }
}
